mapper.select:
SELECT t.id, t.theme_name, t.description, t.price, t.thumbnail_url, t.theme_code,
CASE WHEN tp.id IS NOT NULL OR t.is_default = TRUE THEN TRUE ELSE FALSE END AS is_owned, CASE WHEN m.theme_id = t.id THEN TRUE ELSE FALSE END AS is_applied,
FALSE AS is_owned, FALSE AS is_applied,
t.updated_at, t.created_at FROM theme t
LEFT JOIN theme_purchase tp ON tp.theme_id = t.id AND tp.member_id = #{memberId} AND tp.purchase_status = TRUE LEFT JOIN member m ON m.id = #{memberId}
WHERE t.id = #{themeId}

SELECT price
FROM theme
WHERE id = #{themeId}

SELECT status
FROM theme
WHERE id = #{themeId}

mapper.insert:
INSERT INTO theme_purchase (member_id, theme_id, payment_id, is_used)
SELECT #{memberId}, #{themeId}, NULL, FALSE
WHERE NOT EXISTS (
    SELECT 1
    FROM theme_purchase tp
    WHERE tp.member_id = #{memberId}
      AND tp.theme_id = #{themeId}
)

mapper.select:
SELECT EXISTS (
SELECT 1
FROM theme_purchase tp
WHERE tp.member_id = #{memberId}
AND tp.theme_id = #{themeId}
AND tp.purchase_status = TRUE
)

mapper.update:
UPDATE member
SET theme_id = #{themeId}
WHERE id = #{memberId}

UPDATE theme_purchase
SET is_used = TRUE
WHERE member_id = #{memberId}
AND theme_id = #{themeId}
AND is_used = FALSE
AND tp.purchase_status = TRUE
